    import commonToggleContent from '../common/common-toggle-content.vue';
    export default {
        components: { commonToggleContent },
        props: {
            title: {
                type: String,
                default: "WHAT OUR CLIENTS SAY <span class='text-primary'>ABOUT US</span>",
            },
            buttonText: {
                type: String,
                default: 'VIEW ALL REVIEWS',
            },
            buttonUrl: {
                type: String,
                default: '',
            },
            testimonials: {
                type: Array,
                default: () => [
                    {
                        id: 1,
                        attributes: {
                            name: 'Ted Van Samsung',
                            description: "I'm an executive with global master franchising, and I have collaborated internationally with many entrepreneurs. Arleo ",
                            profileImgUrl: 'https://images.ctfassets.net/koyrlvjc3wvc/5H1y3ht65ezlbwrcC9qVLI/9ddba90f7019732147496420476b7b6a/Ted_Van_Samang.png',
                            rating: 5,
                            googleLink: 'https://google.com',
                            yelpLink: null,
                            companyLink: null,
                            companyName: 'google',
                        },
                    },
                ],
            },
        },

        data() {
            return {
                isMobile: false,
                ratingTextShowMore: false,
                viewAll: false,
                slider_options: {
                    autoplay: {
                        delay: 3000,
                        disableOnInteraction: false,
                    },
                    loop: true,
                    slidesPerView: 1,
                    spaceBetween: 20,
                    touchRatio: 1,
                    init: false,
                    breakpoints: {
                        640: {
                            slidesPerView: 2,
                        },
                        768: {
                            slidesPerView: 2,
                        },
                        1024: {
                            slidesPerView: 3,
                            spaceBetween: 20,
                        },
                        1200: {
                            slidesPerView: 3,
                            spaceBetween: 20,
                        },
                    },
                },
                slider_data: [],
            };
        },
        computed: {},

        mounted() {
            [...this.testimonials].forEach((da) => {
                this.slider_data.push(da);
            });
            this.aboutClient.init();
        },

        methods: {
            truncateString(text) {
                const words = text.split(' ');
                let truncatedText = '';
                for (let i = 0; i < words.length; i++) {
                    if (truncatedText.length + words[i].length <= 100) {
                        truncatedText += words[i] + ' ';
                    } else {
                        break;
                    }
                }
                return truncatedText.trim();
            },
            toggleReadMore(data) {
                data.attributes.readMoreOn = !data.attributes.readMoreOn;
            },
            stopAutoPlay() {
                this.aboutClient.autoplay.stop();
            },

            startAutoPlay() {
                this.aboutClient.autoplay.start();
            },
        },
    };
